package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.io.*;
final class MeetingActions {
 static JSONObject preview(Context c,String id)throws Exception{File folder=MeetingAudioStore.folder(c,id);MeetingAudioStore.meta(folder);File source=new File(folder,"summary.gcm");if(!source.isFile()||source.length()>1000000)throw new IOException("保存済みの要約がありません。文字起こし・要約後に選んでください");String summary=new String(DeviceSecrets.photos().decrypt(Files.readAllBytes(source.toPath())),StandardCharsets.UTF_8);return new JSONObject().put("meetingId",id).put("sourceHash",RecorderPhotoStore.hash(summary.getBytes(StandardCharsets.UTF_8))).put("items",MeetingActionPolicy.candidates(summary));}
 static JSONObject save(Context c,String id,String hash,int index,String text)throws Exception{JSONObject source=preview(c,id);if(!source.getString("sourceHash").equals(hash))throw new IOException("要約が更新されました。候補を開き直してください");JSONArray items=source.getJSONArray("items");if(index<0||index>=items.length()||text==null||text.trim().isEmpty()||text.length()>800)throw new IOException("保留する内容を確認してください");JSONObject item=items.getJSONObject(index);String requestId=java.util.UUID.nameUUIDFromBytes(("meeting:"+id+":"+hash+":"+index).getBytes(StandardCharsets.UTF_8)).toString();String reference=new JSONObject().put("meetingId",id).put("source","会議要約（発言・日付を再確認）").put("excerpt",item.getString("text")).put("conversation",new JSONArray().put(new JSONObject().put("kind","会議要約の記述（確認前の候補）").put("message",item.getString("text")))).toString();return SecretaryInbox.save(c,text.trim(),reference,requestId,new JSONObject().put("subject",text.trim().substring(0,Math.min(160,text.trim().length()))).put("conditions","会議要約から手動確認して保留。日時・担当・出典を実行前に確認"));}
 private MeetingActions(){}
}
